const MARKS = /[̀-֑ͯ-ׇֽֿׁׂًׅׄ-ٰٟ]/gu;
const SAME: Record<string, string> = {"\u2019": "'", "\u2018": "'", "\u02bc": "'", "`": "'", "\u03c2": "\u03c3", "\u064a": "\u06cc", "\u0649": "\u06cc", "\u0643": "\u06a9", "\u200c": "", "\u200d": ""};
